import json

def extract_failed_reason(message):
  json_str = message.split("400 - ", 1)[1]
  clean = json_str.strip('"').encode("utf-8").decode("unicode_escape")
  parsed = json.loads(clean)
  return parsed["error"]["message"]["value"]

for item in _input.all():
  if item.json.error.message.startswith('400 - '):
    item.json.failed_reason = extract_failed_reason(item.json.error.message)
  else:
    item.json.failed_reason = item.json.error.message

return _input.all()

import re

def fn_address_check(addresses):
  nz_po_address_pattern = re.compile(
    r'\b(?:P(?:\.|ost)?\s*O(?:\.|ffice)?\.?\s*Box\s*\d+|'      # e.g., P.O. Box 123, Post Office Box 123
    r'Private\s+Bag\s*\d+|'                                     # e.g., Private Bag 1234
    r'Poste\s+Restante)\b'                                      # e.g., Poste Restante
    r'(?:,\s*[\w\s\-]+)*'                                       # optional: suburb or city, e.g., Auckland Central
    r'(?:,\s*(?:NZ|New Zealand))?'                              # optional: country
    , re.IGNORECASE
)
  if ''.join(addresses) == "":
    return "Failed"
  for address in addresses:
      match = nz_po_address_pattern.search(address)
      if match:
          return "Failed"
  return "Passed"


def fn_order_value_check(order_value):
  order_value = float(order_value)
  if order_value is None or order_value == "":
    return "Failed"

  if order_value > 0 and order_value < 1200:
    return "Passed"
  else: return "Failed"

# Loop over input items and add a new field called 'myNewField' to the JSON of each one
for item in _input.all():
  if item.json.risk_level == "MEDIUM" or item.json.risk_level == "HIGH":
    continue

  item.json.address_check = fn_address_check([item.json.address1 or "", str(item.json.address2 or "")])

  item.json.order_value_check = fn_order_value_check(item.json.current_subtotal_price)

  if item.json.address_check=="Passed" and item.json.order_value_check == "Passed":
    item.json.all_check = "Passed"
  else:
    item.json.all_check = "Failed"

return _input.all()

